import { clinic } from "./content.js";
import { displayPrice, filterCatalog, rub } from "./catalog.js";
import { checkupProgram } from "./checkup-programs.js";
export const offers = [
  {
    id: "checkup",
    title: "Диспансеризация",
    text: `Для кошек и собак: стандартная программа от ${rub(checkupProgram("cat", "clinic", "standard").price)}. Общий и биохимический анализы крови, рентген и УЗИ брюшной полости. Есть расширенные программы.`,
    href: "/offers#checkup-programs",
    question: "Хочу узнать об акции на диспансеризацию.",
    primary: true,
  },
  {
    id: "castration",
    title: "Кастрация",
    text: "Обсудите с клиникой условия акции, консультацию и подготовку к операции.",
    question: "Хочу узнать об акции на кастрацию.",
  },
  {
    id: "sterilization",
    title: "Стерилизация",
    text: "Узнайте условия акции и как записаться на консультацию перед операцией.",
    question: "Хочу узнать об акции на стерилизацию.",
  },
];
export async function answerQuestion(question, loadPrices) {
  const q = question.toLowerCase().replaceAll("ё", "е");
  if (/акци|диспансер/.test(q))
    return {
      text: "По акциям на диспансеризацию, кастрацию и стерилизацию условия и стоимость уточнит администратор. По переписке я не назначаю обследования и не подбираю подготовку к операции.",
      action: "call",
    };
  if (/цен|стоим|сколько|прайс|price/.test(q)) {
    const term = q
      .replace(/[?!.:,]/g, " ")
      .replace(/\bprice\b/g, " ")
      .split(/\s+/)
      .filter(
        (w) =>
          w &&
          !/^(сколько|стоит|стоят|цена|цены|цену|стоимость|прайс|какая|какие|на|за|у|вас|пожалуйста|скажите|подскажите|покажи|покажите|а|и)$/.test(
            w,
          ),
      )
      .join(" ");
    if (!term)
      return {
        text: "Прейскурант обновляется из каталога клиники. Откройте его или напишите, например: «Сколько стоит первичный приём?»",
        href: "/prices",
        label: "Открыть прейскурант",
      };
    try {
      const catalog = await loadPrices();
      const matches = filterCatalog(catalog.items, term, "").slice(0, 4);
      return {
        text: matches.length
          ? "В текущем прейскуранте:\n" +
            matches.map((x) => `${x.title} — ${displayPrice(x)}`).join("\n") +
            "\nИтоговая стоимость зависит от назначенных услуг."
          : "Не нашёл точного совпадения. Попробуйте короткое название услуги или уточните у администратора.",
        href: "/prices?q=" + encodeURIComponent(term),
        label: "Посмотреть все цены",
      };
    } catch {
      return {
        text: "Сейчас не удалось получить актуальные цены. Уточните стоимость в клинике по телефону.",
        action: "call",
      };
    }
  }
  if (/адрес|где|добрать|маршрут/.test(q))
    return {
      text: `Мы находимся по адресу: ${clinic.address}. На странице контактов есть фотография входа и маршрут.`,
      href: "/contacts",
      label: "Как добраться",
    };
  if (/время|час|работаете|график|ночью|круглосуточ/.test(q))
    return {
      text: "Клиника работает круглосуточно. Ночью, с 20:00 до 09:00, перед приездом обязательно позвоните.",
      action: "call",
    };
  if (/запис|администратор|человек|передать|оператор|связаться/.test(q))
    return {
      text: "Время приёма согласует администратор. Сейчас связаться с ним можно по телефону. Этот чат не передаёт сообщения и персональные данные в клинику.",
      action: "handoff",
    };
  if (/подготов|взять|документ/.test(q))
    return {
      text: "Возьмите ветеринарный паспорт, если он есть, прежние заключения и список назначенных препаратов. Подготовку к анализам или операции уточните в клинике.",
      href: "/visit",
      label: "Список перед визитом",
    };
  if (/привет|здравств/.test(q))
    return {
      text: "Здравствуйте! Помогу найти цену, адрес, время работы и информацию перед визитом. Если нужен администратор, подскажу, как связаться.",
    };
  return {
    text: "Я отвечаю на организационные вопросы: цены, адрес, часы работы и запись. Не ставлю диагнозы и не назначаю лечение. Если вопрос о самочувствии питомца или помощь нужна сейчас, позвоните в клинику.",
    action: "call",
  };
}
